// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IEmergencyOracle {
    function owner() external view returns (address);
}

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address jojoTeam, address caller, string calldata description) public {
        vm.assume(jojoTeam != address(0));
        vm.assume(caller != address(0));
        vm.assume(caller != jojoTeam);

        vm.prank(jojoTeam);
        c.setJojoTeam(jojoTeam);

        address oracleAddress;
        vm.prank(caller);
        try c.newEmergencyOracle(description) {
            // read the emitted address is not possible via getters; read the latest oracle via event is not allowed,
            // so instead observe through the oracle ownership: the deployed oracle's owner must equal the caller.
            // Retrieve the oracle address from the event logs via vm is not permitted; use the public getter instead.
            oracleAddress = c.lastOracle();
        } catch {
            oracleAddress = address(0);
        }

        assertTrue(oracleAddress != address(0) && IEmergencyOracle(oracleAddress).owner() == caller);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, string calldata description) public {
        // Admissible domain: a real, nonzero caller creating an oracle.
        vm.assume(caller != address(0));
        // The reference contract always lets a legitimate caller deploy its
        // emergency oracle with the CALLER as owner; the mutant passes
        // jojoTeam (defaulting to address(0)) instead, and EmergencyOracle's
        // constructor reverts on a zero owner, so the call fails.
        vm.prank(caller);
        bool ok;
        try c.newEmergencyOracle(description) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function testInvariant() public {
        require(msg.sender != c.jojoTeam(), "must be non-jojoTeam caller");
        bool reverted = false;
        try c.newEmergencyOracle("d") {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(string calldata description) public {
        bool reverted;
        try c.newEmergencyOracle(description) { reverted = false; } catch { reverted = true; }
        assert(reverted == (msg.sender != c.jojoTeam()));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(string calldata description) public {
        require(bytes(description).length > 0 && c.jojoTeam() != address(0), "precondition failed");
        bool reverted;
        try c.newEmergencyOracle(description) { reverted = false; } catch { reverted = true; }
        assert(reverted == (msg.sender != c.jojoTeam()));
    }
    receive() external payable {}
}

